// classes/BeatManager.ts
class BeatManager {
  _beatData;
  _roundStartTime = 0;
  constructor(beatData) {
    this._beatData = beatData;
  }
  startRound(roundStartTime) {
    this._roundStartTime = roundStartTime;
  }
  getElapsed() {
    return Date.now() - this._roundStartTime;
  }
  getExpectedPlatform(timestamp) {
    const elapsed = timestamp - this._roundStartTime;
    const { beatIndex } = this._findNearestBeat(elapsed);
    if (beatIndex === -1)
      return null;
    const marker = this._beatData.markers[beatIndex];
    return marker === "six" ? 6 : 7;
  }
  validateJump(platform2, timestamp) {
    const elapsed = timestamp - this._roundStartTime;
    const { beatTime, beatIndex, timingDelta } = this._findNearestBeat(elapsed);
    if (beatIndex === -1) {
      return {
        rating: "MISS",
        score: SCORE_MISS,
        timingDelta: 99999,
        eliminate: true
      };
    }
    const expectedMarker = this._beatData.markers[beatIndex];
    const expectedPlatform = expectedMarker === "six" ? 6 : 7;
    if (platform2 !== expectedPlatform) {
      return {
        rating: "WRONG_PLATFORM",
        score: SCORE_MISS,
        timingDelta,
        eliminate: true
      };
    }
    return this._scoreTimingDelta(timingDelta);
  }
  getBeatTimes() {
    return this._beatData.beatTimes;
  }
  getMarkers() {
    return this._beatData.markers;
  }
  getBeatData() {
    return this._beatData;
  }
  _findNearestBeat(elapsed) {
    let nearestBeat = this._beatData.beatTimes[0];
    let nearestIndex = 0;
    let minDelta = Math.abs(elapsed - nearestBeat);
    for (let i4 = 1;i4 < this._beatData.beatTimes.length; i4++) {
      const delta = Math.abs(elapsed - this._beatData.beatTimes[i4]);
      if (delta < minDelta) {
        minDelta = delta;
        nearestBeat = this._beatData.beatTimes[i4];
        nearestIndex = i4;
      }
    }
    if (minDelta > 1000) {
      return { beatTime: 0, beatIndex: -1, timingDelta: minDelta };
    }
    return {
      beatTime: nearestBeat,
      beatIndex: nearestIndex,
      timingDelta: minDelta
    };
  }
  _scoreTimingDelta(timingDelta) {
    if (timingDelta <= PERFECT_TIMING_WINDOW_MS) {
      return {
        rating: "PERFECT",
        score: SCORE_PERFECT,
        timingDelta,
        eliminate: false
      };
    }
    if (timingDelta <= GOOD_TIMING_WINDOW_MS) {
      return {
        rating: "GOOD",
        score: SCORE_GOOD,
        timingDelta,
        eliminate: false
      };
    }
    if (timingDelta <= LATE_TIMING_WINDOW_MS) {
      return {
        rating: "LATE",
        score: SCORE_LATE,
        timingDelta,
        eliminate: false
      };
    }
    return {
      rating: "MISS",
      score: SCORE_MISS,
      timingDelta,
      eliminate: true
    };
  }
}

// classes/GamePlayerEntity.ts
class GamePlayerEntity extends eO {
  _isEliminated = false;
  _currentScore = 0;
  _profile;
  constructor(player) {
    super({
      player,
      name: player.username,
      cosmeticHiddenSlots: []
    });
    this._profile = { ...DEFAULT_PLAYER_PROFILE };
    setImmediate(() => {
      this._setupUIListeners();
    });
  }
  _setupUIListeners() {
    this.player.ui.on(nc.DATA, (eventData) => {
      const data = eventData.data;
      if (data && data.type === "platform-jump") {
        this._handlePlatformJump(data.platform, data.timestamp);
      }
    });
  }
  _handlePlatformJump(platform2, timestamp) {
    if (this._isEliminated)
      return;
    GameManager.instance.handleJump(this.player, platform2, timestamp);
  }
  eliminate() {
    this._isEliminated = true;
    this.player.ui.sendData({
      type: "eliminated",
      finalScore: this._currentScore
    });
  }
  get isEliminated() {
    return this._isEliminated;
  }
  resetForNewMatch() {
    this._isEliminated = false;
    this._currentScore = 0;
  }
  addScore(points) {
    this._currentScore += points;
  }
  get currentScore() {
    return this._currentScore;
  }
  setProfile(profile) {
    this._profile = profile;
  }
  get profile() {
    return this._profile;
  }
  updateProfileAfterMatch(won, perfectHits, goodHits) {
    this._profile.totalMatches++;
    this._profile.totalScore += this._currentScore;
    this._profile.perfectHits += perfectHits;
    this._profile.goodHits += goodHits;
    this._profile.lastPlayedAt = Date.now();
    if (won) {
      this._profile.wins++;
    }
  }
  addXP(amount) {
    this._profile.xp += amount;
    const xpNeeded = this._profile.level * 1000;
    if (this._profile.xp >= xpNeeded) {
      this._profile.level++;
      this._profile.xp -= xpNeeded;
      this.player.ui.sendData({
        type: "level-up",
        level: this._profile.level
      });
      return true;
    }
    return false;
  }
}

// classes/PlatformEntity.ts
class PlatformEntity extends B8 {
  _number;
  constructor(number) {
    const textureUri = number === 6 ? "blocks/grass-block" : "blocks/sandstone";
    super({
      name: `Platform ${number}`,
      blockTextureUri: textureUri,
      blockHalfExtents: {
        x: PLATFORM_SIZE.x / 2,
        y: PLATFORM_SIZE.y / 2,
        z: PLATFORM_SIZE.z / 2
      },
      rigidBodyOptions: {
        type: rG.STATIC
      }
    });
    this._number = number;
  }
  get number() {
    return this._number;
  }
  glow() {}
  stopGlow() {}
}

// classes/GameManager.ts
import { readFileSync } from "fs";
import { join } from "path";

class GameManager {
  static instance = new GameManager;
  world;
  _gameState = "WAITING";
  _currentRound = 0;
  _beatManager;
  _platform6;
  _platform7;
  _roundAudio;
  _alivePlayers = new Set;
  _playerScores = new Map;
  _playerPerfectHits = new Map;
  _playerGoodHits = new Map;
  _roundTimer;
  _countdownTimer;
  _waitTimer;
  _platformGlowTimers = [];
  _lastInputTime = new Map;
  _inputCounts = new Map;
  setupGame(world) {
    this.world = world;
    console.log("[6-7 BATTLEGROUND] Setting up game...");
    this._spawnPlatforms();
    this._waitForPlayers();
    console.log("[6-7 BATTLEGROUND] Game setup complete! Waiting for players...");
    console.log(`[6-7 BATTLEGROUND] ${AUDIO_TRACKS.length} audio tracks available!`);
  }
  spawnPlayerEntity(player) {
    if (!this.world)
      return;
    const playerEntity = new GamePlayerEntity(player);
    playerEntity.spawn(this.world, PLAYER_SPAWN_POSITION);
    this._loadPlayerProfile(player, playerEntity);
    this._syncUIForPlayer(player);
    console.log(`[6-7 BATTLEGROUND] Player ${player.username} spawned`);
  }
  handlePlayerLeave(player) {
    this._alivePlayers.delete(player.id);
    this._playerScores.delete(player.id);
    this._playerPerfectHits.delete(player.id);
    this._playerGoodHits.delete(player.id);
    this._lastInputTime.delete(player.id);
    this._inputCounts.delete(player.id);
    this.world?.entityManager.getPlayerEntitiesByPlayer(player).forEach((entity) => {
      entity.despawn();
    });
    console.log(`[6-7 BATTLEGROUND] Player ${player.username} left`);
  }
  handleJump(player, platform2, timestamp) {
    if (!this._beatManager || this._gameState !== "PLAYING")
      return;
    if (!this._checkInputRateLimit(player)) {
      console.warn(`[ANTI-CHEAT] ${player.username} exceeded input rate limit`);
      return;
    }
    if (!this._alivePlayers.has(player.id))
      return;
    const result = this._beatManager.validateJump(platform2, timestamp);
    const currentScore = this._playerScores.get(player.id) || 0;
    this._playerScores.set(player.id, currentScore + result.score);
    if (result.rating === "PERFECT") {
      const perfects = this._playerPerfectHits.get(player.id) || 0;
      this._playerPerfectHits.set(player.id, perfects + 1);
    } else if (result.rating === "GOOD") {
      const goods = this._playerGoodHits.get(player.id) || 0;
      this._playerGoodHits.set(player.id, goods + 1);
    }
    player.ui.sendData({
      type: "score",
      rating: result.rating,
      score: result.score,
      timingDelta: result.timingDelta,
      totalScore: currentScore + result.score
    });
    if (result.eliminate) {
      this._eliminatePlayer(player);
    }
    this._broadcastLeaderboard();
    console.log(`[GAME] ${player.username} jumped to ${platform2}: ${result.rating} (+${result.score})`);
  }
  get gameState() {
    return this._gameState;
  }
  _spawnPlatforms() {
    if (!this.world)
      return;
    this._platform6 = new PlatformEntity(6);
    this._platform6.spawn(this.world, PLATFORM_6_POSITION);
    this._platform7 = new PlatformEntity(7);
    this._platform7.spawn(this.world, PLATFORM_7_POSITION);
    console.log("[6-7 BATTLEGROUND] Platforms spawned");
  }
  _waitForPlayers() {
    if (!this.world)
      return;
    this._gameState = "WAITING";
    if (this._waitTimer)
      clearTimeout(this._waitTimer);
    this._waitTimer = setInterval(() => {
      if (!this.world)
        return;
      const playerCount = this.world.entityManager.getAllPlayerEntities().length;
      if (playerCount >= MINIMUM_PLAYERS_TO_START) {
        clearInterval(this._waitTimer);
        this._startMatch();
      } else {
        this._broadcastToAll({
          type: "waiting-for-players",
          current: playerCount,
          needed: MINIMUM_PLAYERS_TO_START
        });
      }
    }, 2000);
  }
  _startMatch() {
    if (!this.world)
      return;
    console.log("[6-7 BATTLEGROUND] Match starting!");
    this._currentRound = 0;
    this._alivePlayers.clear();
    this._playerScores.clear();
    this._playerPerfectHits.clear();
    this._playerGoodHits.clear();
    this.world.entityManager.getAllPlayerEntities().forEach((entity) => {
      const gameEntity = entity;
      gameEntity.resetForNewMatch();
      this._alivePlayers.add(entity.player.id);
      this._playerScores.set(entity.player.id, 0);
      this._playerPerfectHits.set(entity.player.id, 0);
      this._playerGoodHits.set(entity.player.id, 0);
    });
    this._startRound();
  }
  _startRound() {
    if (!this.world)
      return;
    this._currentRound++;
    this._gameState = "COUNTDOWN";
    console.log(`[6-7 BATTLEGROUND] Round ${this._currentRound} starting...`);
    this._broadcastToAll({
      type: "round-start",
      round: this._currentRound,
      totalRounds: ROUNDS_PER_MATCH
    });
    this._runCountdown();
  }
  _runCountdown() {
    let countdown = COUNTDOWN_BEFORE_ROUND_SECONDS;
    const countdownInterval = setInterval(() => {
      if (!this.world) {
        clearInterval(countdownInterval);
        return;
      }
      this._broadcastToAll({
        type: "countdown",
        seconds: countdown
      });
      countdown--;
      if (countdown < 0) {
        clearInterval(countdownInterval);
        this._playRound();
      }
    }, 1000);
  }
  _selectTrack() {
    if (AUDIO_TRACKS.length === 0) {
      throw new Error("No audio tracks configured!");
    }
    if (TRACK_SELECTION_MODE === "random") {
      const randomIndex = Math.floor(Math.random() * AUDIO_TRACKS.length);
      return AUDIO_TRACKS[randomIndex];
    } else if (TRACK_SELECTION_MODE === "sequential") {
      const trackIndex = this._currentRound % AUDIO_TRACKS.length;
      return AUDIO_TRACKS[trackIndex];
    }
    return AUDIO_TRACKS[0];
  }
  _loadBeatTimingData(beatTimingsUri) {
    try {
      const filePath = join(process.cwd(), "assets", beatTimingsUri);
      const fileContent = readFileSync(filePath, "utf-8");
      return JSON.parse(fileContent);
    } catch (error) {
      console.error(`[6-7 BATTLEGROUND] Failed to load beat timing data from ${beatTimingsUri}:`, error);
      throw error;
    }
  }
  _playRound() {
    if (!this.world)
      return;
    this._gameState = "PLAYING";
    const selectedTrack = this._selectTrack();
    console.log(`[6-7 BATTLEGROUND] Selected track: ${selectedTrack.name}`);
    const beatTimingData = this._loadBeatTimingData(selectedTrack.beatTimingsUri);
    this._beatManager = new BeatManager(beatTimingData);
    const roundStartTime = Date.now();
    this._beatManager.startRound(roundStartTime);
    this._roundAudio = new PW({
      uri: selectedTrack.uri,
      loop: false,
      volume: 0.8
    });
    this._roundAudio.play(this.world);
    this._broadcastToAll({
      type: "track-selected",
      trackName: selectedTrack.name
    });
    console.log("[6-7 BATTLEGROUND] Round playing! Audio started.");
    this._schedulePlatformGlows();
    this._roundTimer = setTimeout(() => {
      this._endRound();
    }, selectedTrack.durationMs);
  }
  _schedulePlatformGlows() {
    if (!this._beatManager)
      return;
    this._clearPlatformGlowTimers();
    const beatTimes = this._beatManager.getBeatTimes();
    const markers = this._beatManager.getMarkers();
    beatTimes.forEach((beatTime, index) => {
      const marker = markers[index];
      const platformNumber = marker === "six" ? 6 : 7;
      const highlightStartDelay = Math.max(0, beatTime - 300);
      const highlightTimer = setTimeout(() => {
        this._broadcastToAll({
          type: "platform-highlight",
          platform: platformNumber,
          active: true
        });
      }, highlightStartDelay);
      this._platformGlowTimers.push(highlightTimer);
      const highlightStopDelay = beatTime + 500;
      const stopTimer = setTimeout(() => {
        this._broadcastToAll({
          type: "platform-highlight",
          platform: platformNumber,
          active: false
        });
      }, highlightStopDelay);
      this._platformGlowTimers.push(stopTimer);
    });
    console.log(`[6-7 BATTLEGROUND] Scheduled ${beatTimes.length} platform UI highlights`);
  }
  _clearPlatformGlowTimers() {
    this._platformGlowTimers.forEach((timer) => clearTimeout(timer));
    this._platformGlowTimers = [];
    this._broadcastToAll({
      type: "platform-highlight",
      platform: 0,
      active: false
    });
  }
  _endRound() {
    if (!this.world)
      return;
    this._gameState = "ROUND_END";
    this._clearPlatformGlowTimers();
    console.log(`[6-7 BATTLEGROUND] Round ${this._currentRound} ended`);
    this._alivePlayers.forEach((playerId) => {
      const entities = this.world.entityManager.getAllPlayerEntities();
      const entity = entities.find((e2) => e2.player.id === playerId);
      if (entity) {
        entity.addXP(XP_ROUND_SURVIVED);
      }
    });
    if (this._currentRound >= ROUNDS_PER_MATCH || this._alivePlayers.size <= 1) {
      setTimeout(() => this._endMatch(), 3000);
    } else {
      setTimeout(() => this._startRound(), SECONDS_BETWEEN_ROUNDS * 1000);
    }
  }
  _endMatch() {
    if (!this.world)
      return;
    this._gameState = "MATCH_END";
    console.log("[6-7 BATTLEGROUND] Match ended!");
    let winnerPlayerId = null;
    let highestScore = -1;
    this._playerScores.forEach((score, playerId) => {
      if (score > highestScore) {
        highestScore = score;
        winnerPlayerId = playerId;
      }
    });
    let winnerUsername = "Unknown";
    if (winnerPlayerId) {
      const winnerEntity = this.world.entityManager.getAllPlayerEntities().find((e2) => e2.player.id === winnerPlayerId);
      if (winnerEntity) {
        winnerUsername = winnerEntity.player.username;
        const gameEntity = winnerEntity;
        gameEntity.addXP(XP_MATCH_WIN);
        const perfects = this._playerPerfectHits.get(winnerPlayerId) || 0;
        const goods = this._playerGoodHits.get(winnerPlayerId) || 0;
        gameEntity.updateProfileAfterMatch(true, perfects, goods);
        this._savePlayerProfile(winnerEntity.player, gameEntity);
      }
    }
    this.world.entityManager.getAllPlayerEntities().forEach((entity) => {
      if (entity.player.id !== winnerPlayerId) {
        const gameEntity = entity;
        const perfects = this._playerPerfectHits.get(entity.player.id) || 0;
        const goods = this._playerGoodHits.get(entity.player.id) || 0;
        gameEntity.updateProfileAfterMatch(false, perfects, goods);
        gameEntity.addXP(XP_MATCH_COMPLETE);
        this._savePlayerProfile(entity.player, gameEntity);
      }
    });
    this._broadcastToAll({
      type: "match-end",
      winner: winnerUsername,
      winnerScore: highestScore,
      round: this._currentRound
    });
    setTimeout(() => {
      this._waitForPlayers();
    }, WINNER_ANNOUNCEMENT_DURATION_MS);
  }
  _eliminatePlayer(player) {
    this._alivePlayers.delete(player.id);
    const entity = this.world?.entityManager.getAllPlayerEntities().find((e2) => e2.player.id === player.id);
    if (entity) {
      entity.eliminate();
      entity.setPosition(SPECTATOR_POSITION);
    }
    console.log(`[6-7 BATTLEGROUND] Player ${player.username} eliminated`);
    if (this._alivePlayers.size <= 1 && this._gameState === "PLAYING") {
      if (this._roundTimer)
        clearTimeout(this._roundTimer);
      this._endMatch();
    }
  }
  _checkInputRateLimit(player) {
    const now = Date.now();
    const lastTime = this._lastInputTime.get(player.id) || 0;
    if (now - lastTime > 1000) {
      this._inputCounts.set(player.id, 0);
    }
    const count = this._inputCounts.get(player.id) || 0;
    this._inputCounts.set(player.id, count + 1);
    this._lastInputTime.set(player.id, now);
    return count < 10;
  }
  _broadcastToAll(data) {
    if (!this.world)
      return;
    TQ.instance.playerManager.getConnectedPlayersByWorld(this.world).forEach((player) => {
      player.ui.sendData(data);
    });
  }
  _broadcastLeaderboard() {
    if (!this.world)
      return;
    const leaderboard = [];
    this._playerScores.forEach((score, playerId) => {
      const entity = this.world.entityManager.getAllPlayerEntities().find((e2) => e2.player.id === playerId);
      if (entity) {
        const gameEntity = entity;
        leaderboard.push({
          username: entity.player.username,
          score,
          alive: !gameEntity.isEliminated
        });
      }
    });
    leaderboard.sort((a, b3) => b3.score - a.score);
    this._broadcastToAll({
      type: "leaderboard",
      players: leaderboard
    });
  }
  _syncUIForPlayer(player) {
    player.ui.sendData({
      type: "game-state",
      state: this._gameState,
      round: this._currentRound,
      totalRounds: ROUNDS_PER_MATCH
    });
    this._broadcastLeaderboard();
  }
  async _loadPlayerProfile(player, entity) {
    try {
      const data = await player.getPersistedData();
      if (data && Object.keys(data).length > 0) {
        entity.setProfile(data);
        console.log(`[6-7 BATTLEGROUND] Loaded profile for ${player.username}: Level ${data.level}`);
      } else {
        entity.setProfile({ ...DEFAULT_PLAYER_PROFILE });
        await player.setPersistedData(DEFAULT_PLAYER_PROFILE);
        console.log(`[6-7 BATTLEGROUND] Created new profile for ${player.username}`);
      }
    } catch (error) {
      console.error(`[6-7 BATTLEGROUND] Error loading profile for ${player.username}:`, error);
      entity.setProfile({ ...DEFAULT_PLAYER_PROFILE });
    }
  }
  async _savePlayerProfile(player, entity) {
    try {
      await player.setPersistedData(entity.profile);
      console.log(`[6-7 BATTLEGROUND] Saved profile for ${player.username}`);
    } catch (error) {
      console.error(`[6-7 BATTLEGROUND] Error saving profile for ${player.username}:`, error);
    }
  }
}
